function validate([beginWord, endWord, wordList]) {
  const lower = /^[a-z]+$/;
  if (typeof beginWord !== 'string' || beginWord.length < 1 || beginWord.length > 5) return 'beginWord needs 1 to 5 letters.';
  if (typeof endWord !== 'string' || endWord.length !== beginWord.length) return 'endWord must be as long as beginWord.';
  if (!lower.test(beginWord) || !lower.test(endWord)) return 'Words use lowercase letters only.';
  if (beginWord === endWord) return 'beginWord and endWord must differ.';
  if (!Array.isArray(wordList) || wordList.length < 1 || wordList.length > 500) return 'wordList needs 1 to 500 words.';
  const words = new Set();
  for (const word of wordList) {
    if (typeof word !== 'string' || word.length !== beginWord.length || !lower.test(word)) return 'Every word in wordList must be lowercase and as long as beginWord.';
    if (words.has(word)) return 'The words in wordList must be distinct.';
    words.add(word);
  }
  // Count the shortest ladders so their total size stays within the problem's limit.
  const dist = new Map([[beginWord, 0]]);
  const ways = new Map([[beginWord, 1]]);
  let level = [beginWord];
  while (level.length > 0 && !dist.has(endWord)) {
    const next = [];
    for (const word of level) for (let i = 0; i < word.length; i++) for (let code = 97; code <= 122; code++) {
      const cand = word.slice(0, i) + String.fromCharCode(code) + word.slice(i + 1);
      if (!words.has(cand)) continue;
      if (!dist.has(cand)) { dist.set(cand, dist.get(word) + 1); ways.set(cand, 0); next.push(cand); }
      if (dist.get(cand) === dist.get(word) + 1) ways.set(cand, ways.get(cand) + ways.get(word));
    }
    level = next;
  }
  if (dist.has(endWord) && ways.get(endWord) * (dist.get(endWord) + 1) > 100000) return 'The shortest ladders together may hold at most 10^5 words.';
  return null;
}

