function findLadders(beginWord, endWord, wordList) {
  const unvisited = new Set(wordList);
  if (!unvisited.has(endWord)) return [];
  unvisited.delete(beginWord);
  const buckets = new Map();
  for (const word of wordList) {
    for (let i = 0; i < word.length; i++) {
      const pattern = word.slice(0, i) + '*' + word.slice(i + 1);
      if (!buckets.has(pattern)) buckets.set(pattern, []);
      buckets.get(pattern).push(word);
    }
  }
  const parents = new Map();
  let level = [beginWord];
  let found = false;

  while (level.length > 0 && !found) {
    const next = new Map();
    for (const word of level) {
      for (let i = 0; i < word.length; i++) {
        const pattern = word.slice(0, i) + '*' + word.slice(i + 1);
        for (const candidate of buckets.get(pattern) || []) {
          if (!unvisited.has(candidate)) continue;
          if (!next.has(candidate)) next.set(candidate, []);
          next.get(candidate).push(word);
          if (candidate === endWord) found = true;
        }
      }
    }
    for (const [word, from] of next) {
      unvisited.delete(word);
      parents.set(word, from);
    }
    level = [...next.keys()];
  }

  const result = [];
  if (!found) return result;
  const path = [endWord];
  function backtrack(word) {
    if (word === beginWord) {
      result.push([...path].reverse());
      return;
    }
    for (const parent of parents.get(word)) {
      path.push(parent);
      backtrack(parent);
      path.pop();
    }
  }
  backtrack(endWord);
  return result;
}

