function findLadders(beginWord, endWord, wordList) {
  if (!wordList.includes(endWord)) return [];
  const oneApart = (a, b) => {
    let diff = 0;
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) diff++;
    return diff === 1;
  };
  // Distance from every dictionary word to endWord, by BFS that compares words pairwise.
  const toEnd = new Map([[endWord, 0]]);
  const queue = [endWord];
  for (let head = 0; head < queue.length; head++) {
    for (const word of wordList) {
      if (!toEnd.has(word) && oneApart(queue[head], word)) { toEnd.set(word, toEnd.get(queue[head]) + 1); queue.push(word); }
    }
  }
  let steps = Infinity;
  for (const word of wordList) if (toEnd.has(word) && oneApart(beginWord, word)) steps = Math.min(steps, toEnd.get(word) + 1);
  if (steps === Infinity) return [];
  // Walk forward from beginWord, always to a word exactly one step closer to endWord.
  const ladders = [];
  const walk = (chain, word, left) => {
    if (left === 0) { ladders.push(chain.slice()); return; }
    for (const nextWord of wordList) {
      if (toEnd.get(nextWord) !== left - 1 || !oneApart(word, nextWord)) continue;
      chain.push(nextWord);
      walk(chain, nextWord, left - 1);
      chain.pop();
    }
  };
  walk([beginWord], beginWord, steps);
  return ladders;
}

