function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const configs = size === 'large'
    ? [{ len: 5, alphabet: 'abcd', n: 500 }, { len: 4, alphabet: 'abcdef', n: 500 }, { len: 3, alphabet: 'abcdefghijklmnopqrstuvwxyz', n: 500 }]
    : [{ len: 1, alphabet: 'abcd', n: 3 }, { len: 2, alphabet: 'abc', n: 7 }, { len: 3, alphabet: 'ab', n: 7 }, { len: 3, alphabet: 'abc', n: 8 }];
  for (;;) {
    const { len, alphabet, n } = pick(configs);
    const makeWord = () => Array.from({ length: len }, () => pick(alphabet)).join('');
    const count = size === 'large' ? n : 1 + Math.floor(rand() * n);
    const set = new Set();
    while (set.size < count) set.add(makeWord());
    const wordList = [...set];
    const beginWord = rand() < 0.3 ? pick(wordList) : makeWord();
    // Breadth-first search from beginWord: distance and number of shortest routes to each word.
    const dist = new Map([[beginWord, 0]]);
    const ways = new Map([[beginWord, 1]]);
    let level = [beginWord];
    while (level.length > 0) {
      const next = [];
      for (const word of level) for (let i = 0; i < len; i++) for (const ch of alphabet) {
        const cand = word.slice(0, i) + ch + word.slice(i + 1);
        if (!set.has(cand)) continue;
        if (!dist.has(cand)) { dist.set(cand, dist.get(word) + 1); ways.set(cand, 0); next.push(cand); }
        if (dist.get(cand) === dist.get(word) + 1) ways.set(cand, ways.get(cand) + ways.get(word));
      }
      level = next;
    }
    let endWord;
    if (size === 'large' && rand() < 0.85) {
      const far = Math.max(...[...dist.values()]);
      endWord = pick([...dist.keys()].filter(w => dist.get(w) === far));
    } else {
      endWord = rand() < 0.85 ? pick(wordList) : makeWord();
    }
    if (endWord === beginWord) continue;
    if (dist.has(endWord) && ways.get(endWord) * (dist.get(endWord) + 1) > 100000) continue;
    if (size === 'large' && rand() < 0.5) wordList.reverse();
    return [beginWord, endWord, wordList];
  }
}
